// .devcontainer/devcontainer.json
{
  "name": "App backend",
  "dockerComposeFile": "../compose.yaml",  // réutiliser le stack (db, cache...)
  "service": "api",
  "workspaceFolder": "/app",
  "forwardPorts": [8080, 5432],
  "customizations": {
    "vscode": {
      "extensions": ["redhat.java", "esbenp.prettier-vscode"]
    }
  },
  "postCreateCommand": "mvn -q dependency:go-offline"
}
